<?php require_role('student');$pageTitle='Project Documents';$pageSubtitle='Maintain an organised version history';$project=project_for_student((int)current_user()['id']);$docs=$project?db_all("SELECT d.*,u.full_name uploader FROM documents d JOIN users u ON u.id=d.uploaded_by WHERE d.project_id=? ORDER BY d.id DESC",[$project['id']]):[];include __DIR__.'/../includes/layout_top.php'; ?>
<div class="split-grid"><section class="card"><div class="card-header"><div><h2>Upload a new version</h2><p>Accepted formats: PDF, DOC and DOCX; maximum 5 MB.</p></div></div><?php if(!$project): ?><div class="callout">No project assignment is available.</div><?php else: ?><form method="post" enctype="multipart/form-data" action="<?= e(url('actions.php')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="upload_document"><div class="form-group"><label>Project file</label><input type="file" name="document" accept=".pdf,.doc,.docx" required></div><div class="form-group"><label>Description</label><textarea name="description" placeholder="Example: Revised Chapter Three after the session held on 25 July."></textarea></div><button class="button" type="submit">Upload document</button></form><?php endif; ?></section><section class="card"><div class="card-header"><h2>Document control</h2></div><div class="callout">Each upload receives a sequential version number, date, file size and uploader identity. Keep sensitive research data out of the application unless institutional approval and appropriate safeguards are in place.</div></section></div>
<div class="card"><div class="card-header"><div><h2>Version history</h2><p><?= count($docs) ?> uploaded document(s)</p></div></div><?php if(!$docs): ?><div class="empty-state">No documents have been uploaded.</div><?php else: foreach($docs as $d): ?><div class="document-item"><div style="display:flex;align-items:center;gap:12px"><div class="file-icon">V<?= (int)$d['version_no'] ?></div><div><strong><?= e($d['original_name']) ?></strong><div class="muted"><?= e($d['description']) ?> · <?= number_format($d['file_size']/1024,1) ?> KB · <?= e(format_date($d['created_at'])) ?></div></div></div><a class="button small secondary" href="<?= e(url('download.php?id='.(int)$d['id'])) ?>" target="_blank" rel="noopener">Open</a></div><?php endforeach; endif; ?></div>
